      else requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  });
  const elapsed = performance.now() - t0;
  return { frames, elapsedMs: Math.round(elapsed), fps: Math.round((frames / elapsed) * 1000 * 10) / 10 };
}, ms);

