  const stillOnDisk = report.phases.continue.storageAfterContinue.find((w) => w.savedSamples > 0);
  say(`stored WorldSave after Continue: ${JSON.stringify(report.phases.continue.storageAfterContinue)}`);
  if (!stillOnDisk) {
