  }

  // ---------------------------------------------------------- PHASE 1: earn ---
  say('PHASE 1 — earn a real partial drawing on the EARNED Origin');
  const earn0 = Date.now();
  let cg = null; let st = null;
  let lastGrowthAt = Date.now(); let lastSamples = -1;
  let purity = null;
