  const w = window;
  if (w.__voxContinueSampler) return;
  const rec = { t0: performance.now(), frames: [], stopped: false, missing: {} };
  w.__voxContinueSampler = rec;
  const tick = () => {
    if (rec.stopped) return;
    const s = w.__paravoxiaCommonGround?.snapshot?.() ?? null;
    const vd = w.__voxelDebug?.spawn ?? null;
    const sysHook = w.__paravoxiaSystem?.snapshot?.() ?? null;
    rec.frames.push({
      ms: Math.round(performance.now() - rec.t0),
      beat: w.__storyBeat ?? null,
      beatPublished: Object.prototype.hasOwnProperty.call(w, '__storyBeat'),
      activePlanetId: sysHook?.activePlanetId ?? null,
      renderOrigin: s?.renderOrigin ?? s?.worldBound ?? null,
      cgFoot: s?.bodyPose ? [...s.bodyPose] : null,
      capsule: s?.bodyCentre ? [...s.bodyCentre] : null,
      up: s?.up ? [...s.up] : null,
      terrainSeed: vd ? (vd.terrainSeed ?? null) : null,
      playerRequested: vd?.playerRequested ? [...vd.playerRequested] : null,
      voxelDebugPublished: !!vd
    });
    if (rec.frames.length < 6000) requestAnimationFrame(tick);
    else rec.stopped = true;
  };
  requestAnimationFrame(tick);
});
