    samplesSurvived: after ? after.samples === before.samples : false,
    walkedUnitsSurvived: after ? Math.abs((after.walkedUnits ?? -1) - (before.walkedUnits ?? -2)) < 1e-6 : false,
    phaseAfterContinue: after?.phase ?? null,
