    ...gates,
    allHeld: Object.values(gates).every((v) => v === true),
    note: 'A restored survey is NOT sufficient. actualAcceptedNewAction requires the shipped [F] prompt to have been offered, pressed unforced, and to have produced a real phase change or anc.cg.route-offered.'
  };
