      key: w.key, bytes: w.raw.length, sha256: sha(w.raw), file,
      worldId: parsed?.worldId ?? null, seed: parsed?.seed ?? null,
      hasCommonGround: cgBlob != null,
      commonGroundSha256: cgBlob ? sha(JSON.stringify(cgBlob)) : null,
